mapper.select:
SELECT mr.*, u.real_name AS teacher_name, st.student_name AS student_name, st.student_code AS student_number, CASE WHEN mr.question_id < 0 THEN CAST(-mr.question_id AS CHAR) ELSE pq.question_no END AS question_no, (SELECT image_url FROM answer_sheet_image WHERE answer_sheet_id = mr.answer_sheet_id LIMIT 1) AS answer_image_url, (SELECT image_url FROM answer_sheet_image WHERE answer_sheet_id = mr.answer_sheet_id LIMIT 1) AS original_image_url FROM marking_record mr LEFT JOIN sys_user u ON mr.teacher_id = u.id LEFT JOIN student st ON mr.student_id = st.id LEFT JOIN paper_question pq ON mr.question_id = pq.id WHERE mr.task_id = #{taskId}
AND mr.teacher_id = #{teacherId}
AND mr.status = #{status}
ORDER BY mr.create_time

SELECT * FROM marking_record
WHERE answer_sheet_id = #{answerSheetId}
AND question_id = #{questionId}
ORDER BY marking_role

SELECT COUNT(*) + 1
FROM marking_record
WHERE task_id = #{taskId}
AND marking_role = #{markingRole}
AND status = 0
AND id < #{recordId}
